def orientations(mat, reflect=True):
    res=[]
    for f in ([False,True] if reflect else [False]):
        a=[row[:] for row in mat]
        if f: a=[row[::-1] for row in a]
        for k in range(4):
            b=a
            for _ in range(k): b=[list(row) for row in zip(*b[::-1])]
            t=tuple(tuple(row) for row in b)
            if t not in res:res.append(t)
